package eu.kanade.tachiyomi.animesource.online

import eu.kanade.tachiyomi.animesource.AnimeCatalogueSource
import eu.kanade.tachiyomi.animesource.model.AnimeFilterList
import eu.kanade.tachiyomi.animesource.model.AnimesPage
import eu.kanade.tachiyomi.animesource.model.Hoster
import eu.kanade.tachiyomi.animesource.model.Hoster.Companion.toHosterList
import eu.kanade.tachiyomi.animesource.model.SAnime
import eu.kanade.tachiyomi.animesource.model.SEpisode
import eu.kanade.tachiyomi.animesource.model.Video
import eu.kanade.tachiyomi.network.GET
import eu.kanade.tachiyomi.network.NetworkHelper
import eu.kanade.tachiyomi.network.ProgressListener
import eu.kanade.tachiyomi.network.asObservableSuccess
import eu.kanade.tachiyomi.network.awaitSuccess
import eu.kanade.tachiyomi.network.newCachelessCallWithProgress
import eu.kanade.tachiyomi.util.lang.awaitSingle
import okhttp3.Headers
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.Response
import rx.Observable
import uy.kohesive.injekt.injectLazy
import java.net.URI
import java.net.URISyntaxException
import java.security.MessageDigest

/**
 * A simple implementation for sources from a website.
 *
 * Hibiki host ABI: the union of extensions-lib 14 and extensions-lib 16 (as compiled
 * against by the yuzono / Anikku ecosystem and the Aniyomi main line). Every member
 * that one generation declares abstract and the other never heard of is `open` with
 * a throwing default here, otherwise the JVM would refuse to instantiate the other
 * generation's extension classes. The hoster API is the single entry point the host
 * drives: [getHosterList] detects at runtime which generation a source implements
 * and routes the legacy video list through a [Hoster.NO_HOSTER_LIST] hoster.
 */
@Suppress("unused")
abstract class AnimeHttpSource : AnimeCatalogueSource {
    /**
     * Network service.
     */
    val network: NetworkHelper by injectLazy()

    /**
     * Base url of the website without the trailing slash, like: http://mysite.com
     */
    abstract val baseUrl: String

    /**
     * Version id used to generate the source id. If the site completely changes and urls are
     * incompatible, you may increase this value and it'll be considered as a new source.
     */
    open val versionId = 1

    /**
     * ID of the source. By default it uses a generated id using the first 16 characters (64 bits)
     * of the MD5 of the string `"${name.lowercase()}/$lang/$versionId"`.
     *
     * The ID is generated by the [generateId] function, which can be reused if needed
     * to generate outdated IDs for cases where the source name or language needs to
     * be changed but migrations can be avoided.
     *
     * Note: the generated ID sets the sign bit to `0`.
     */
    override val id by lazy { generateId(name, lang, versionId) }

    /**
     * Headers used for requests.
     */
    val headers: Headers by lazy { headersBuilder().build() }

    /**
     * Default network client for doing requests.
     */
    open val client: OkHttpClient
        get() = network.client

    /**
     * Generates a unique ID for the source based on the provided [name], [lang] and
     * [versionId]. It will use the first 16 characters (64 bits) of the MD5 of the string
     * `"${name.lowercase()}/$lang/$versionId"`.
     *
     * Note: the generated ID sets the sign bit to `0`.
     *
     * Can be used to generate outdated IDs, such as when the source name or language
     * needs to be changed but migrations can be avoided.
     *
     * @since extensions-lib 15
     * @param name [String] the name of the source
     * @param lang [String] the language of the source
     * @param versionId [Int] the version ID of the source
     * @return a unique ID for the source
     */
    @Suppress("MemberVisibilityCanBePrivate")
    protected fun generateId(
        name: String,
        lang: String,
        versionId: Int,
    ): Long {
        val key = "${name.lowercase()}/$lang/$versionId"
        val bytes = MessageDigest.getInstance("MD5").digest(key.toByteArray())
        return (0..7).map { bytes[it].toLong() and 0xff shl 8 * (7 - it) }.reduce(Long::or) and Long.MAX_VALUE
    }

    /**
     * Headers builder for requests. Implementations can override this method for custom headers.
     */
    protected open fun headersBuilder() =
        Headers.Builder().apply {
            add("User-Agent", network.defaultUserAgentProvider())
        }

    /**
     * Visible name of the source.
     */
    override fun toString() = "$name (${lang.uppercase()})"

    /**
     * Returns an observable containing a page with a list of anime. Normally it's not needed to
     * override this method.
     *
     * @param page the page number to retrieve.
     */
    @Deprecated(
        "Use the non-RxJava API instead",
        ReplaceWith("getPopularAnime"),
    )
    override fun fetchPopularAnime(page: Int): Observable<AnimesPage> =
        client
            .newCall(popularAnimeRequest(page))
            .asObservableSuccess()
            .map { response ->
                popularAnimeParse(response)
            }

    /**
     * Returns the request for the popular anime given the page.
     *
     * @param page the page number to retrieve.
     */
    protected abstract fun popularAnimeRequest(page: Int): Request

    /**
     * Parses the response from the site and returns a [AnimesPage] object.
     *
     * @param response the response from the site.
     */
    protected abstract fun popularAnimeParse(response: Response): AnimesPage

    /**
     * Returns an observable containing a page with a list of anime. Normally it's not needed to
     * override this method.
     *
     * @param page the page number to retrieve.
     * @param query the search query.
     * @param filters the list of filters to apply.
     */
    @Deprecated(
        "Use the non-RxJava API instead",
        ReplaceWith("getSearchAnime"),
    )
    override fun fetchSearchAnime(
        page: Int,
        query: String,
        filters: AnimeFilterList,
    ): Observable<AnimesPage> =
        Observable
            .defer {
                try {
                    client.newCall(searchAnimeRequest(page, query, filters)).asObservableSuccess()
                } catch (e: NoClassDefFoundError) {
                    // RxJava doesn't handle Errors, which tends to happen during global searches
                    // if an old extension using non-existent classes is still around
                    throw RuntimeException(e)
                }
            }.map { response ->
                searchAnimeParse(response)
            }

    /**
     * Returns the request for the search anime given the page.
     *
     * @param page the page number to retrieve.
     * @param query the search query.
     * @param filters the list of filters to apply.
     */
    protected abstract fun searchAnimeRequest(
        page: Int,
        query: String,
        filters: AnimeFilterList,
    ): Request

    /**
     * Parses the response from the site and returns a [AnimesPage] object.
     *
     * @param response the response from the site.
     */
    protected abstract fun searchAnimeParse(response: Response): AnimesPage

    /**
     * Returns an observable containing a page with a list of latest anime updates.
     *
     * @param page the page number to retrieve.
     */
    @Deprecated(
        "Use the non-RxJava API instead",
        ReplaceWith("getLatestUpdates"),
    )
    override fun fetchLatestUpdates(page: Int): Observable<AnimesPage> =
        client
            .newCall(latestUpdatesRequest(page))
            .asObservableSuccess()
            .map { response ->
                latestUpdatesParse(response)
            }

    /**
     * Returns the request for latest anime given the page.
     *
     * @param page the page number to retrieve.
     */
    protected abstract fun latestUpdatesRequest(page: Int): Request

    /**
     * Parses the response from the site and returns a [AnimesPage] object.
     *
     * @param response the response from the site.
     */
    protected abstract fun latestUpdatesParse(response: Response): AnimesPage

    /**
     * Get the updated details for a anime.
     * Normally it's not needed to override this method.
     *
     * @param anime the anime to be updated.
     * @return the updated anime.
     */
    @Suppress("DEPRECATION")
    override suspend fun getAnimeDetails(anime: SAnime): SAnime = fetchAnimeDetails(anime).awaitSingle()

    @Deprecated("Use the non-RxJava API instead", replaceWith = ReplaceWith("getAnimeDetails"))
    override fun fetchAnimeDetails(anime: SAnime): Observable<SAnime> =
        client
            .newCall(animeDetailsRequest(anime))
            .asObservableSuccess()
            .map { response ->
                animeDetailsParse(response).apply { initialized = true }
            }

    /**
     * Returns the request for the details of an anime. Override only if it's needed to change the
     * url, send different headers or request method like POST.
     *
     * @param anime the anime to be updated.
     */
    open fun animeDetailsRequest(anime: SAnime): Request = GET(baseUrl + anime.url, headers)

    /**
     * Parses the response from the site and returns the details of an anime.
     *
     * @param response the response from the site.
     */
    protected abstract fun animeDetailsParse(response: Response): SAnime

    // KMK -->
    override val supportsRelatedAnimes: Boolean get() = true

    /**
     * Fetch related animes for a anime from source/site. The host never calls this;
     * it exists so Anikku-flavoured extensions overriding it link.
     *
     * @since komikku/extensions-lib 1.6
     */
    override suspend fun fetchRelatedAnimeList(anime: SAnime): List<SAnime> =
        client
            .newCall(relatedAnimeListRequest(anime))
            .awaitSuccess()
            .let { response -> relatedAnimeListParse(response) }

    protected open fun relatedAnimeListRequest(anime: SAnime): Request = animeDetailsRequest(anime)

    protected open fun relatedAnimeListParse(response: Response): List<SAnime> = popularAnimeParse(response).animes
    // KMK <--

    /**
     * Get all the available episodes for an anime.
     * Normally it's not needed to override this method.
     *
     * @param anime the anime to update.
     * @return the chapters for the manga.
     * @throws LicensedEntryItemsException if a anime is licensed and therefore no episodes are available.
     */
    @Suppress("DEPRECATION")
    override suspend fun getEpisodeList(anime: SAnime): List<SEpisode> {
        if (anime.status == SAnime.LICENSED) {
            throw LicensedEntryItemsException()
        }

        return fetchEpisodeList(anime).awaitSingle()
    }

    @Deprecated("Use the non-RxJava API instead", replaceWith = ReplaceWith("getEpisodeList"))
    override fun fetchEpisodeList(anime: SAnime): Observable<List<SEpisode>> =
        if (anime.status != SAnime.LICENSED) {
            client
                .newCall(episodeListRequest(anime))
                .asObservableSuccess()
                .map(::episodeListParse)
        } else {
            Observable.error(Exception(LicensedEntryItemsException()))
        }

    /**
     * Returns the request for updating the episode list. Override only if it's needed to override
     * the url, send different headers or request method like POST.
     *
     * @param anime the anime to look for episodes.
     */
    protected open fun episodeListRequest(anime: SAnime): Request = GET(baseUrl + anime.url, headers)

    /**
     * Parses the response from the site and returns a list of episodes.
     *
     * @param response the response from the site.
     */
    protected abstract fun episodeListParse(response: Response): List<SEpisode>

    /**
     * Parses the response from the site and returns a SEpisode Object.
     *
     * lib 14 declared this abstract; lib 16 dropped it. Open so lib-16 classes load.
     *
     * @param response the response from the site.
     */
    protected open fun episodeVideoParse(response: Response): SEpisode = throw UnsupportedOperationException()

    // AY -->
    /**
     * Get all the available seasons for an anime.
     * Normally it's not needed to override this method.
     *
     * @since extensions-lib 16
     * @param anime the anime to look for seasons.
     * @return the seasons for the anime.
     */
    override suspend fun getSeasonList(anime: SAnime): List<SAnime> =
        client
            .newCall(seasonListRequest(anime))
            .awaitSuccess()
            .let { response -> seasonListParse(response) }

    /**
     * Returns the request for updating the season list. Override only if it's needed to override
     * the url, send different headers or request method like POST.
     *
     * @since extensions-lib 16
     */
    protected open fun seasonListRequest(anime: SAnime): Request = GET(baseUrl + anime.url, headers)

    /**
     * Parses the response from the site and returns a list of seasons.
     *
     * lib 16 declares this abstract; open here so lib-14 classes load.
     *
     * @since extensions-lib 16
     */
    protected open fun seasonListParse(response: Response): List<SAnime> = throw UnsupportedOperationException()
    // <-- AY

    /**
     * Get the list of hoster for an episode. The first hoster in the list should
     * be the preferred hoster.
     *
     * Generation switch: a source that implements the lib-16 parser
     * ([hosterListParse]) gets the hoster request; anything else is a lib-14 source
     * whose [getVideoList] (episode) is wrapped in one [Hoster.NO_HOSTER_LIST]
     * hoster, exactly as Aniyomi's own compatibility shim does. Decided by
     * reflection on the class hierarchy, never by issuing a request and watching
     * it fail: [hosterListRequest] would otherwise hit `baseUrl + episode.url` once
     * per episode for every lib-14 source.
     *
     * @since extensions-lib 16
     * @param episode the episode.
     * @return the hosters for the episode.
     */
    override suspend fun getHosterList(episode: SEpisode): List<Hoster> {
        if (!implementsHosterParser) {
            return getVideoList(episode).toHosterList()
        }
        return client
            .newCall(hosterListRequest(episode))
            .awaitSuccess()
            .let { response -> hosterListParse(response) }
    }

    /**
     * Returns the request for getting the hosters. Override only if it's needed to override
     * the url, send different headers or request method like POST.
     *
     * @since extensions-lib 16
     */
    protected open fun hosterListRequest(episode: SEpisode): Request = GET(baseUrl + episode.url, headers)

    /**
     * Parses the response from the site and returns a list of hosters.
     *
     * lib 16 declares this abstract; open here so lib-14 classes load.
     *
     * @since extensions-lib 16
     */
    protected open fun hosterListParse(response: Response): List<Hoster> = throw UnsupportedOperationException()

    /**
     * Get the list of videos for a hoster.
     *
     * @since extensions-lib 16
     * @param hoster the hoster.
     * @return the videos for the hoster.
     */
    override suspend fun getVideoList(hoster: Hoster): List<Video> {
        hoster.videoList?.let { return it }
        return client
            .newCall(videoListRequest(hoster))
            .awaitSuccess()
            .let { response -> videoListParse(response, hoster) }
    }

    /**
     * Returns the request for getting the hoster's videos. Override only if it's needed to
     * override the url, send different headers or request method like POST.
     *
     * @since extensions-lib 16
     */
    protected open fun videoListRequest(hoster: Hoster): Request = GET(hoster.hosterUrl, headers)

    /**
     * Parses the response from the hoster and returns a list of videos.
     *
     * @since extensions-lib 16
     */
    protected open fun videoListParse(
        response: Response,
        hoster: Hoster,
    ): List<Video> = throw UnsupportedOperationException()

    /**
     * Returns the resolved video of the episode link. Override only if it's needed to resolve
     * the video.
     *
     * @since extensions-lib 16
     * @param video the video information.
     * @return the resolved video, or null on failure
     */
    open suspend fun resolveVideo(video: Video): Video? = video

    /**
     * Get the list of videos a episode has. Videos should be returned
     * in the expected order; the index is ignored.
     *
     * @param episode the episode.
     * @return the videos for the episode.
     */
    @Suppress("DEPRECATION")
    override suspend fun getVideoList(episode: SEpisode): List<Video> = fetchVideoList(episode).awaitSingle()

    @Deprecated("Use the non-RxJava API instead", replaceWith = ReplaceWith("getVideoList"))
    override fun fetchVideoList(episode: SEpisode): Observable<List<Video>> =
        client
            .newCall(videoListRequest(episode))
            .asObservableSuccess()
            .map { response ->
                videoListParse(response).sort()
            }

    /**
     * Returns the request for getting the episode link. Override only if it's needed to override
     * the url, send different headers or request method like POST.
     *
     * @param episode the episode to look for links.
     */
    protected open fun videoListRequest(episode: SEpisode): Request = GET(baseUrl + episode.url, headers)

    /**
     * Parses the response from the site and returns a list of videos.
     *
     * lib 14 declares this abstract; open here so lib-16 classes load.
     *
     * @param response the response from the site.
     */
    protected open fun videoListParse(response: Response): List<Video> = throw UnsupportedOperationException()

    /**
     * Sorts the hoster list. Override this according to the user's preference.
     *
     * @since extensions-lib 16
     */
    open fun List<Hoster>.sortHosters(): List<Hoster> = this

    /**
     * Sorts the video list. Override this according to the user's preference.
     *
     * @since extensions-lib 16
     */
    @Suppress("DEPRECATION")
    protected open fun List<Video>.sortVideos(): List<Video> = sort()

    /**
     * Sorts the video list. Override this according to the user's preference.
     */
    @Deprecated("Use .sortVideos() instead", replaceWith = ReplaceWith("sortVideos"))
    protected open fun List<Video>.sort(): List<Video> = this

    /**
     * Host entry points for the protected sort hooks: the extension's preference
     * driven ordering is applied once per hoster, as the Aniyomi player does.
     */
    fun applyHosterSort(hosters: List<Hoster>): List<Hoster> = hosters.sortHosters()

    fun applyVideoSort(videos: List<Video>): List<Video> = videos.sortVideos()

    /**
     * Returns an observable with the page containing the source url of the image. If there's any
     * error, it will return null instead of throwing an exception.
     *
     * @since extensions-lib 15
     * @param video the video whose source image has to be fetched.
     */
    @Suppress("DEPRECATION")
    open suspend fun getVideoUrl(video: Video): String = fetchVideoUrl(video).awaitSingle()

    @Deprecated("Use the non-RxJava API instead", replaceWith = ReplaceWith("getVideoUrl"))
    open fun fetchVideoUrl(video: Video): Observable<String> =
        client
            .newCall(videoUrlRequest(video))
            .asObservableSuccess()
            .map(::videoUrlParse)

    /**
     * Returns the request for getting the url to the source image. Override only if it's needed to
     * override the url, send different headers or request method like POST.
     *
     * @param video the chapter whose page list has to be fetched
     */
    protected open fun videoUrlRequest(video: Video): Request = GET(video.url, headers)

    /**
     * Parses the response from the site and returns the absolute url to the source image.
     *
     * lib 14 declares this abstract; open here so lib-16 classes load.
     *
     * @param response the response from the site.
     */
    protected open fun videoUrlParse(response: Response): String = throw UnsupportedOperationException()

    /**
     * Returns the response of the source video.
     * Typically does not need to be overridden.
     *
     * @since extensions-lib 15
     * @param video the video whose source video has to be downloaded.
     */
    open suspend fun getVideo(video: Video): Response =
        client
            .newCachelessCallWithProgress(videoRequest(video), NoOpProgressListener)
            .awaitSuccess()

    /**
     * Returns the response of the source video.
     *
     * @since extensions-lib 16
     * @param request the http request for the video that has to be downloaded.
     * @param listener the progress listener that has to be attached to the http request
     */
    suspend fun getVideo(
        request: Request,
        listener: ProgressListener,
    ): Response =
        client
            .newCachelessCallWithProgress(request, listener)
            .awaitSuccess()

    /**
     * Returns the request for getting the source image. Override only if it's needed to override
     * the url, send different headers or request method like POST.
     *
     * @param video the video whose link has to be fetched
     */
    protected open fun videoRequest(
        video: Video,
        bytes: Long = 0L,
    ): Request {
        val headers = video.headers ?: headers
        val newHeaders =
            if (bytes > 0L) {
                headers.newBuilder().add("Range", "bytes=$bytes-").build()
            } else {
                headers
            }
        return GET(if (video.isVideoUrlUnresolved) video.url else video.videoUrl, newHeaders)
    }

    /**
     * Assigns the url of the episode without the scheme and domain. It saves some redundancy from
     * database and the urls could still work after a domain change.
     *
     * @param url the full url to the episode.
     */
    fun SEpisode.setUrlWithoutDomain(url: String) {
        this.url = getUrlWithoutDomain(url)
    }

    /**
     * Assigns the url of the anime without the scheme and domain. It saves some redundancy from
     * database and the urls could still work after a domain change.
     *
     * @param url the full url to the anime.
     */
    fun SAnime.setUrlWithoutDomain(url: String) {
        this.url = getUrlWithoutDomain(url)
    }

    /**
     * Returns the url of the given string without the scheme and domain.
     *
     * @param orig the full url.
     */
    private fun getUrlWithoutDomain(orig: String): String =
        try {
            val uri = URI(orig)
            var out = uri.path
            if (uri.query != null) {
                out += "?" + uri.query
            }
            if (uri.fragment != null) {
                out += "#" + uri.fragment
            }
            out
        } catch (e: URISyntaxException) {
            orig
        }

    /**
     * Returns the url of the provided anime
     *
     * @since extensions-lib 14
     * @param anime the anime
     * @return url of the anime
     */
    open fun getAnimeUrl(anime: SAnime): String = animeDetailsRequest(anime).url.toString()

    /**
     * Returns the url of the provided episode
     *
     * @since extensions-lib 14
     * @param episode the episode
     * @return url of the episode
     */
    open fun getEpisodeUrl(episode: SEpisode): String = episode.url.toString()

    /**
     * Called before inserting a new episode into database. Use it if you need to override episode
     * fields, like the title or the episode number. Do not change anything to [anime].
     *
     * @param episode the episode to be added.
     * @param anime the anime of the episode.
     */
    open fun prepareNewEpisode(
        episode: SEpisode,
        anime: SAnime,
    ) {}

    /**
     * Returns the list of filters for the source.
     */
    override fun getFilterList() = AnimeFilterList()

    /**
     * Whether the extension (not a host base class) declares the lib-16 hoster
     * parser. Cached: the answer is a property of the class, and the check walks
     * the hierarchy with reflection. [ParsedAnimeHttpSource] widens it to its
     * selector hooks.
     */
    protected open val implementsHosterParser: Boolean by lazy {
        declaresOverride("hosterListParse", Response::class.java)
    }

    /**
     * True when a class the extension ships declares the method. The walk stops at
     * the host ABI package: host base classes such as [ParsedAnimeHttpSource] also
     * override these hooks, so stopping at "not [AnimeHttpSource]" would misreport
     * every parsed source as lib 16. Extension classes live under
     * `eu.kanade.tachiyomi.animeextension` / vendor packages, never under the ABI
     * package.
     */
    protected fun declaresOverride(
        name: String,
        vararg parameterTypes: Class<*>,
    ): Boolean {
        var type: Class<*>? = javaClass
        while (type != null && !type.name.startsWith(HOST_ABI_PACKAGE_PREFIX)) {
            val declared =
                try {
                    type.getDeclaredMethod(name, *parameterTypes)
                } catch (_: NoSuchMethodException) {
                    null
                }
            if (declared != null) return true
            type = type.superclass
        }
        return false
    }

    private object NoOpProgressListener : ProgressListener {
        override fun update(
            bytesRead: Long,
            contentLength: Long,
            done: Boolean,
        ) {}
    }

    private companion object {
        const val HOST_ABI_PACKAGE_PREFIX = "eu.kanade.tachiyomi.animesource."
    }
}

class LicensedEntryItemsException : Exception("Licensed - No items to show")
